#!/bin/bash
set -e

source "$(dirname "$0")/common.sh"
COMPOSE_FILE="./docker-compose.v2.yml"
if [ -f "$COMPOSE_FILE" ]; then
    COMPOSE_CMD=$(get_compose_cmd)
    $COMPOSE_CMD -f "$COMPOSE_FILE" down --volumes --remove-orphans
fi

# These paths are generated by the v2 launcher; never remove the metrics_server source.
sudo rm -rf -- ./data_v2 ./logs_dump ./startup_v2 ./log_processor.out ./docker-compose.v2.yml
